 try:
  c=sqlite3.connect('file:'+str(f)+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
  tables=[r[0] for r in c.execute('select name from sqlite_master where type="table"')]
  for table in tables:
   if table!='executions':continue
   for r in c.execute('select * from executions'):
    x=dict(r);rows.append({'block':f.parents[2].name,'execution_id':x.get('execution_id'),'state':x.get('state')})
  c.close()
 except Exception as e:rows.append({'ledger':str(f),'error':type(e).__name__+':'+str(e)})
